int main(void){PIXELFORMATDESCRIPTOR p={0};HWND w=CreateWindowA("STATIC","WineMetalGL share",WS_OVERLAPPEDWINDOW,0,0,64,64,0,0,0,0);HDC d=GetDC(w);p.nSize=sizeof(p);p.nVersion=1;p.dwFlags=PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL;p.iPixelType=PFD_TYPE_RGBA;p.cColorBits=32;GB gen_buffers;BB bind_buffer;BD buffer_data;ISB is_buffer;int f=ChoosePixelFormat(d,&p);if(!f||!SetPixelFormat(d,f,&p))return 12;HGLRC a=wglCreateContext(d),b=wglCreateContext(d);if(!a||!b)return 13;if(!wglMakeCurrent(d,a))return 13;gen_buffers=(GB)wglGetProcAddress("glGenBuffers");bind_buffer=(BB)wglGetProcAddress("glBindBuffer");buffer_data=(BD)wglGetProcAddress("glBufferData");is_buffer=(ISB)wglGetProcAddress("glIsBuffer");if(!gen_buffers||!bind_buffer||!buffer_data||!is_buffer)return 13;if(!wglShareLists(a,b))return 14;GLuint texture=0,buffer=0;unsigned char pixel[4]={255,0,0,255};float vertex[3]={0,0,0};wglMakeCurrent(d,a);glGenTextures(1,&texture);glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,1,1,0,GL_RGBA,GL_UNSIGNED_BYTE,pixel);gen_buffers(1,&buffer);bind_buffer(0x8892,buffer);buffer_data(0x8892,sizeof(vertex),vertex,0x88E4);wglMakeCurrent(d,b);if(!glIsTexture(texture)||!is_buffer(buffer))return 15;printf("WINEMETALGL_WGL_SHARE_LISTS_OK\n");printf("WINEMETALGL_WGL_SHARED_OBJECTS_OK\n");wglDeleteContext(a);wglDeleteContext(b);ReleaseDC(w,d);DestroyWindow(w);return 0;}
